"""Phone layout rules. Used when someone picks Phone on the welcome page, or automatically on narrow screens."""

PHONE_RULES = "html, body, .stApp { overflow-x: hidden; } .block-container, [data-testid=\"stMainBlockContainer\"] { padding: 0.8rem 0.85rem 3rem !important; max-width: 100% !important; } /* top menu: logo + language + theme on one row, page tabs scroll sideways below */ .st-key-fm-navbar { padding: 8px 10px !important; } .st-key-fm-navbar [data-testid=\"stHorizontalBlock\"] { flex-wrap: wrap !important; gap: 8px !important; align-items: center !important; } .st-key-fm-navbar [data-testid=\"stColumn\"] { min-width: 0 !important; width: auto !important; } .st-key-fm-navbar [data-testid=\"stColumn\"]:nth-child(1) { order: 1; flex: 1 1 auto !important; } .st-key-fm-navbar [data-testid=\"stColumn\"]:nth-child(3) { order: 2; flex: 0 0 112px !important; } .st-key-fm-navbar [data-testid=\"stColumn\"]:nth-child(4) { order: 3; flex: 0 0 98px !important; } .st-key-fm-navbar [data-testid=\"stColumn\"]:nth-child(2) { order: 4; flex: 1 1 100% !important; min-width: 100% !important; overflow-x: auto; } .st-key-fm-navbar [data-testid=\"stColumn\"]:nth-child(5) { display: none !important; } .st-key-fm-navbar [role=\"radiogroup\"] { flex-wrap: nowrap !important; overflow-x: auto; gap: 4px !important; padding-bottom: 2px; } .st-key-fm-navbar [role=\"radiogroup\"] label { white-space: nowrap; flex: 0 0 auto; } /* device cards: compact tiles, two per row (icon + name + Diagnose button only) */ [data-testid=\"stHorizontalBlock\"]:has([class*=\"st-key-fm-cat-\"]) { flex-direction: row !important; flex-wrap: wrap !important; gap: 8px !important; } [data-testid=\"stHorizontalBlock\"]:has([class*=\"st-key-fm-cat-\"]) > [data-testid=\"stColumn\"] { flex: 0 0 calc(50% - 4px) !important; min-width: calc(50% - 4px) !important; width: calc(50% - 4px) !important; } [class*=\"st-key-fm-cat-\"] { padding: 8px !important; } [class*=\"st-key-fm-cat-\"] .fm-device-card { padding: 12px !important; min-height: 0 !important; } [class*=\"st-key-fm-cat-\"] .fm-device-card-body p, [class*=\"st-key-fm-cat-\"] .fm-device-card-tag, [class*=\"st-key-fm-cat-\"] .fm-device-index { display: none !important; } [class*=\"st-key-fm-cat-\"] .fm-icon-tile { width: 42px !important; height: 42px !important; } [class*=\"st-key-fm-cat-\"] .fm-device-card h3 { font-size: 1rem !important; margin: 8px 0 0 !important; line-height: 1.15 !important; } [class*=\"st-key-fm-cat-\"] .stButton > button { min-height: 38px !important; font-size: 0.85rem !important; padding: 0 4px !important; } /* tighter cards everywhere else */ .fm-step-card, .fm-feature-card, .fm-principle, .fm-pipeline-step, .fm-about-panel { padding: 14px !important; } /* text sizes and spacing */ .fm-hero h1 { font-size: 2.3rem !important; line-height: 1.06 !important; } .fm-hero-sub { font-size: 1rem !important; } .fm-hero-assurance { flex-wrap: wrap; gap: 8px; } .stApp h2 { font-size: 1.65rem !important; } .fm-section-title-row { flex-direction: column !important; align-items: flex-start !important; gap: 10px !important; } .fm-ticker { margin: 22px -0.85rem !important; padding: 10px 0 !important; } .fm-ticker span { font-size: 0.95rem !important; } .bp { max-height: 260px; } .bp-stage { padding: 6px; } /* easier to tap, and no zoom-in when typing on iPhone */ .stButton > button, .stFormSubmitButton > button, .st-key-fm-repair-shop a { min-height: 48px !important; } .stApp input, .stApp textarea, .stApp [data-baseweb=\"select\"] * { font-size: 16px !important; } .st-key-lang-splash { margin-top: 6vh; } .st-key-lang-splash .stButton > button { min-height: 68px; font-size: 1.2rem !important; } .st-key-fm-footer .fm-footer { padding: 22px 16px !important; } /* long words never push the page sideways */ .stApp [class*=\"fm-\"] { overflow-wrap: anywhere; } .pf-stats { grid-template-columns: 1fr 1fr; } .pf-stat { border-right: 0; border-bottom: 1px solid var(--line); padding: 16px 18px; } .pf-steps, .pf-features, .pf-band { grid-template-columns: 1fr; } .pf-band { padding: 24px; margin-top: 44px; } .pf-row { grid-template-columns: 1fr 84px 38px; } .pf-hero h1 { font-size: 2.1rem !important; } .pf-head { margin-top: 44px; } .st-key-pf-cta { padding: 28px 18px; margin-top: 44px; } .st-key-fm-navbar { border-radius: 12px !important; }"

# Extra rules that make a wide screen (laptop) show the app as one narrow phone-style column.
PHONE_FRAME = ".block-container, [data-testid=\"stMainBlockContainer\"] { max-width: 480px !important; margin-left: auto !important; margin-right: auto !important; } [data-testid=\"stHorizontalBlock\"] { flex-wrap: wrap !important; } [data-testid=\"stColumn\"] { flex: 1 1 100% !important; min-width: 100% !important; }"
